//! The service worker's update lifecycle with two signed releases (#146, docs/e2ee.md §9.3): a
//! verified update waits until the user reloads, every page is served from the release it was loaded
//! with, and a retired release's cache goes once no page uses it. All of this needs a pinned release
//! key, which the unsigned build of the other browser tests does not have.
//!
//! The key is generated by the test and only pinned into the copies of the web build the test serves;
//! the build in `target/e2e-web` keeps its placeholder, so no shipped build can carry it. Release 2 is
//! not a second Trunk build: both releases are made from the one unsigned build, each with its own
//! marker file and `sw.js` comment, and signed with `sign-web-release.sh` like the real release (the
//! service worker only updates when `sw.js` differs, and a release is what its manifest lists).
//! "Deploying" swaps the symlink the server under test serves its web client from.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{Duration, Instant};

use chromiumoxide::page::Page;
use teamcraft_e2e::browser::web_dir;

use crate::web::{Rig, WEB_ORIGIN, click_text, sign_in_as_alice, wait_for_text};
use crate::web_split::wait_for_verified_worker;

const VERSION_1: &str = "e2e-release-1";
const VERSION_2: &str = "e2e-release-2";
/// Fetched by pages only when first used (`.nnef` is on demand for the signed manifest, so the worker
/// never fetches it in the background), and identical in both releases.
const LAZY_FILE: &str = "/e2e-lazy.nnef";
const LAZY_CONTENT: &str = "a file that loads when it is first used";
/// The worker forgets a page that is gone only after this (sw.js, `NEW_CLIENT_GRACE_MS`).
const CLIENT_GRACE: Duration = Duration::from_secs(60);
const WAIT: Duration = Duration::from_secs(90);

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_verified_update_waits_for_the_reload_and_the_old_release_goes_with_its_last_page() {
  let Some(unsigned) = web_dir() else {
    // Rig::start says why it skips (or fails when the web build is required).
    assert!(Rig::start().await.is_none());
    return;
  };
  let Some(releases) = Releases::make(&unsigned) else {
    return;
  };
  let Some(rig) = Rig::start_with(|builder| builder.with_web_dir(releases.current.clone()), &[]).await else {
    return;
  };
  let browser = &rig.browser;
  let releases_ref = &releases;
  browser
    .screenshot_on_failure("web-sw-update", |first| async move {
      // The worker installs release 1 and controls the page before anything navigates, so that every
      // page of this test is one the worker recorded with its release.
      first.goto(format!("{WEB_ORIGIN}/")).await.unwrap();
      wait_for_verified_worker(&first).await;
      sign_in_as_alice(&first).await;
      wait_for_text(&first, "browser-channel").await;
      wait_for_verified_worker(&first).await;

      // A second tab of the same browser: it is the inactive one ("already open in another tab").
      let second = browser
        .new_page(&format!("{WEB_ORIGIN}/?backend=server"))
        .await;
      wait_for_text(&second, "TeamCraft is already open in another tab").await;
      wait_for_verified_worker(&second).await;
      let second_opened = Instant::now();
      eval(
        &second,
        "window.__controllerChanges = 0; \
         navigator.serviceWorker.addEventListener('controllerchange', () => window.__controllerChanges++);",
      )
      .await;
      assert_eq!(marker(&first).await, "release 1");
      assert_eq!(marker(&second).await, "release 1");
      assert!(
        !is_cached(&second, VERSION_1, LAZY_FILE).await,
        "the lazy file was fetched before a page asked for it"
      );
      let first_origin = time_origin(&first).await;
      let second_origin = time_origin(&second).await;

      // Release 2 goes live; the tabs check for it (pages do on their own when they become visible,
      // at most every 15 minutes).
      releases_ref.deploy_second();
      eval(
        &first,
        "navigator.serviceWorker.getRegistration().then((registration) => registration.update())",
      )
      .await;
      wait_until(&first, "a verified release 2 waiting", || {
        "navigator.serviceWorker.getRegistration().then((registration) => !!registration.waiting)"
      })
      .await;
      wait_for_text(&first, "A new version of TeamCraft is ready.").await;

      // No tab switches by itself: neither reloaded, both are still served from release 1, and the
      // worker did not take over.
      tokio::time::sleep(Duration::from_secs(3)).await;
      assert_eq!(time_origin(&first).await, first_origin, "the first tab reloaded by itself");
      assert_eq!(time_origin(&second).await, second_origin, "the second tab reloaded by itself");
      assert_eq!(marker(&first).await, "release 1");
      assert_eq!(marker(&second).await, "release 1");
      assert_eq!(eval(&second, "window.__controllerChanges").await, 0);
      // A file of release 1 that nobody asked for yet still loads, checked against release 1's
      // signed hash, though the server serves release 2 now.
      assert_eq!(fetch_text(&second, LAZY_FILE).await, LAZY_CONTENT);
      assert!(is_cached(&second, VERSION_1, LAZY_FILE).await);

      // "Reload now" switches this tab to release 2 ...
      click_text(&first, "Reload now").await;
      wait_until(&first, "the first tab reloaded", || {
        format!("String(performance.timeOrigin) !== {first_origin:?}")
      })
      .await;
      wait_until(&first, "release 2 in the first tab", || {
        "fetch('/release-marker.txt', { cache: 'no-store' }).then((r) => r.text()).then((t) => t === 'release 2')"
      })
      .await;
      // ... and the other tab keeps working on release 1: it was told that a new worker controls
      // pages, but it did not reload, still gets release 1's files, and release 1's cache is there.
      wait_until(&second, "the controller change to reach the second tab", || {
        "window.__controllerChanges === 1"
      })
      .await;
      assert_eq!(time_origin(&second).await, second_origin, "the second tab reloaded by itself");
      assert_eq!(marker(&second).await, "release 1");
      assert_eq!(fetch_text(&second, LAZY_FILE).await, LAZY_CONTENT);
      let caches = cache_names(&second).await;
      assert!(
        caches.iter().any(|name| name.ends_with(VERSION_1)),
        "release 1's cache went while a tab still runs it: {caches:?}"
      );
      assert!(caches.iter().any(|name| name.ends_with(VERSION_2)), "{caches:?}");

      // Once the last tab runs release 2 too, release 1's cache goes. The worker counts a page that
      // is gone as alive for a minute after it loaded; wait that out, then reload the second tab.
      if let Some(rest) = (second_opened + CLIENT_GRACE + Duration::from_secs(5))
        .checked_duration_since(Instant::now())
      {
        tokio::time::sleep(rest).await;
      }
      second.reload().await.unwrap();
      wait_until(&second, "release 2 in the second tab", || {
        "fetch('/release-marker.txt', { cache: 'no-store' }).then((r) => r.text()).then((t) => t === 'release 2')"
      })
      .await;
      wait_until(&second, "release 1's cache to go", || {
        format!(
          "caches.keys().then((names) => !names.some((name) => name.endsWith('{VERSION_1}')))"
        )
      })
      .await;
      let caches = cache_names(&second).await;
      assert!(caches.iter().any(|name| name.ends_with(VERSION_2)), "{caches:?}");
      assert_eq!(marker(&first).await, "release 2");
    })
    .await;
  releases.remove();
  rig.finish().await;
}

/// The two signed releases and the symlink the server serves.
struct Releases {
  root: PathBuf,
  /// What the server under test serves as its web client.
  current: PathBuf,
  second: PathBuf,
}

impl Releases {
  /// `None` (the test skips, or fails under `E2E_REQUIRED=1`) without `openssl` and `python3`, which
  /// `sign-web-release.sh` needs.
  fn make(unsigned: &Path) -> Option<Self> {
    let has_tools = ["openssl", "python3"].iter().all(|tool| {
      Command::new(tool)
        .arg("version")
        .output()
        .or_else(|_| Command::new(tool).arg("--version").output())
        .is_ok()
    });
    if !has_tools {
      let is_required = std::env::var("E2E_REQUIRED").is_ok_and(|value| value == "1");
      assert!(!is_required, "openssl and python3 are needed to sign a release");
      eprintln!("skipping: openssl and python3 are needed to sign a release");
      return None;
    }
    let sw = std::fs::read_to_string(unsigned.join("sw.js")).unwrap();
    assert!(
      sw.contains("__RELEASE_PUBLIC_KEY__"),
      "the web build is signed already; the test pins its own key into copies of an unsigned one"
    );
    let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("sw-update-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    // A key made for this test; it never leaves this directory.
    let key = root.join("test-release-key.pem");
    let status = Command::new("openssl")
      .args(["genpkey", "-algorithm", "ed25519", "-out"])
      .arg(&key)
      .status()
      .unwrap();
    assert!(status.success(), "generating a test release key failed");
    let first = root.join("release-1");
    let second = root.join("release-2");
    for (number, dist, version) in [(1, &first, VERSION_1), (2, &second, VERSION_2)] {
      make_release(unsigned, dist, &key, number, version);
    }
    let current = root.join("current");
    std::os::unix::fs::symlink(&first, &current).unwrap();
    Some(Self {
      root,
      current,
      second,
    })
  }

  /// A deploy: the server serves release 2 from the next request on.
  fn deploy_second(&self) {
    let next = self.root.join("current-next");
    std::os::unix::fs::symlink(&self.second, &next).unwrap();
    std::fs::rename(&next, &self.current).unwrap();
  }

  fn remove(self) {
    let _ = std::fs::remove_dir_all(&self.root);
  }
}

/// A release made of the unsigned build: its own marker file and `sw.js` text (the browser updates a
/// worker only when its script differs), signed with the test key as the release workflow signs.
fn make_release(unsigned: &Path, dist: &Path, key: &Path, number: u32, version: &str) {
  mirror(unsigned, dist);
  std::fs::write(dist.join("release-marker.txt"), format!("release {number}")).unwrap();
  std::fs::write(dist.join(LAZY_FILE.trim_start_matches('/')), LAZY_CONTENT).unwrap();
  let sw = dist.join("sw.js");
  let mut script = std::fs::read_to_string(&sw).unwrap();
  script.push_str(&format!("\n// e2e release {number}\n"));
  // The copy was made first (not linked): signing rewrites this file.
  std::fs::write(&sw, script).unwrap();
  let script =
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../crates/teamcraft-ui/scripts/sign-web-release.sh");
  let status = Command::new("sh")
    .arg(script)
    .arg(dist)
    .arg(key)
    .arg(version)
    .status()
    .unwrap();
  assert!(status.success(), "signing release {number} failed");
}

/// Copies the tree, linking files where the file system allows (signing only rewrites `sw.js`, which
/// is copied, and adds `release.json`). Precompressed variants are left out: they would go stale.
fn mirror(from: &Path, to: &Path) {
  std::fs::create_dir_all(to).unwrap();
  for entry in std::fs::read_dir(from).unwrap() {
    let entry = entry.unwrap();
    let name = entry.file_name();
    let target = to.join(&name);
    if entry.file_type().unwrap().is_dir() {
      mirror(&entry.path(), &target);
      continue;
    }
    let name = name.to_string_lossy();
    if name.ends_with(".br") || name.ends_with(".gz") {
      continue;
    }
    let is_rewritten = name == "sw.js";
    if is_rewritten || std::fs::hard_link(entry.path(), &target).is_err() {
      std::fs::copy(entry.path(), &target).unwrap();
    }
  }
}

/// Runs a script in the page and returns its (awaited) result.
async fn eval(page: &Page, script: &str) -> serde_json::Value {
  let wrapped = format!("(async () => {{ return await ({script}); }})()");
  page
    .evaluate(wrapped)
    .await
    .unwrap_or_else(|error| panic!("the page script failed: {error}\n{script}"))
    .into_value()
    .unwrap_or_else(|error| panic!("the page script returned something unexpected: {error}\n{script}"))
}

/// Polls until a script (an expression, a promise of one) is true.
async fn wait_until<S: AsRef<str>>(page: &Page, what: &str, script: impl Fn() -> S) {
  let deadline = Instant::now() + WAIT;
  loop {
    let script = script();
    let done = page
      .evaluate(format!(
        "(async () => {{ return await ({}); }})()",
        script.as_ref()
      ))
      .await
      .ok()
      .and_then(|result| result.into_value::<bool>().ok())
      .unwrap_or(false);
    if done {
      return;
    }
    assert!(Instant::now() < deadline, "no {what} within {WAIT:?}");
    tokio::time::sleep(Duration::from_millis(250)).await;
  }
}

/// The marker file as this page gets it: the worker answers from the release the page was loaded with.
async fn marker(page: &Page) -> String {
  fetch_text(page, "/release-marker.txt").await
}

async fn fetch_text(page: &Page, path: &str) -> String {
  eval(
    page,
    &format!("fetch({path:?}, {{ cache: 'no-store' }}).then((response) => response.ok ? response.text() : 'HTTP ' + response.status)"),
  )
  .await
  .as_str()
  .unwrap_or_default()
  .to_owned()
}

async fn time_origin(page: &Page) -> String {
  eval(page, "String(performance.timeOrigin)")
    .await
    .as_str()
    .unwrap_or_default()
    .to_owned()
}

async fn cache_names(page: &Page) -> Vec<String> {
  serde_json::from_value(eval(page, "caches.keys()").await).unwrap()
}

async fn is_cached(page: &Page, version: &str, path: &str) -> bool {
  eval(
    page,
    &format!(
      "caches.open('teamcraft-release-{version}').then((cache) => cache.match({path:?})).then((hit) => !!hit)"
    ),
  )
  .await
  .as_bool()
  .unwrap_or(false)
}
